return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Japanese','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:28+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ja','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" が保存されました。','"%1$s" created. %2$d template updated.'=>'「%1$s」が作成されました。%2$d テンプレートが更新されました。' . "\0" . '','"%s" created.'=>'「%s」が作成されました。','%d language not yet linked'=>'%d言語はまだリンクされていません' . "\0" . '','%d link updated.'=>'%d 個のリンクが更新されました。' . "\0" . '','%d locale pack installed.'=>'%d個のロケールパックがインストールされています。' . "\0" . '','%d navigation reference updated.'=>'%d 個のナビゲーション参照が更新されました。' . "\0" . '','%d part reference updated.'=>'%d 個の部分参照が更新されました。' . "\0" . '','%s Archive'=>'%s アーカイブ','(avg %.1f hits/block)'=>'(平均 %.1f ヒット/ブロック)','(avg %.1f hits/entry)'=>'（平均 %.1f ヒット/エントリ）','(disabled)'=>'（無効）','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} は置換可能なリンクがありませんでした — 調査のために再スキャンしてください)','.txt file(s) in the directory'=>'.txtファイルがディレクトリにあります','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> &#8220;%2$s&#8221; テーマからのローカライズされたテンプレート %1$d 個はデータベースに保存されていますが、現在は非アクティブです。それらは、そのテーマを再アクティブにすると再び有効になります。新しいテーマに翻訳を引き継ぐには、<strong>設定 → Lingua Forge → ルーター → FSEスキャフォールド</strong>を通じて再生成してください。','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> 自動修正可能なリンク','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> 手動レビューが必要なリンク','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> 古いパス','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> テンプレートの問題','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'コンパイル済みの.moファイルのみを受け付けます。ファイル名は{textdomain}-{locale}.moのパターンに従う必要があります。同じ名前のファイルをアップロードすると置き換えられます。','Action'=>'アクション','Actions'=>'アクション','active'=>'アクティブ','Active Languages'=>'アクティブな言語','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'アクティブな言語：サポートしたい各言語を追加してください。各言語にはURLプレフィックスまたはサブドメインと、ページの&lt;head&gt;内にhreflangタグが設定されます。','Active Provider'=>'アクティブなプロバイダー','Add entry'=>'エントリを追加','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'ドラフトを改善するための指示を追加します。例：短くする、結論セクションを追加、よりフォーマルな表現を使う、FAQブロックを含める…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'ドラフトを改善するための指示を追加してください — 例：短くする、結論セクションを追加、よりフォーマルな表現を使う…','Add new entry'=>'新しいエントリを追加','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'1行につき1つの用語を追加します。ソース用語とターゲットのレンダリングの両方が必要です。言語ペアは、制約が適用される翻訳ジョブを決定します。','Adds a link to the home page so visitors can browse in their language.'=>'訪問者が自分の言語で閲覧できるようにホームページへのリンクを追加します。','Administrators only (manage_options)'=>'管理者のみ（manage_options）','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'プライマリ言語を変更した後、URLルーティングを更新するためにパーマリンクをフラッシュしてください。','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL構造設定（パスプレフィックス ↔ サブドメイン）を変更した後は、常に設定 → パーマリンクを訪れて、「変更を保存」をクリックして書き換えルールをフラッシュしてください。','AI Behaviour Preset'=>'AI動作プリセット','AI cache cleared. %d entry was removed.'=>'AIキャッシュがクリアされました。%d件のエントリが削除されました。' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AIキャッシュ：キャッシュされたAI応答とヒット数を一覧表示します。キャッシュ全体または特定の投稿のエントリをクリアします。翻訳変更をテストする前に「クリア」を使用してください — キャッシュされた結果は、AIプリセットやモデルを変更してもキャッシュエントリが追い出されるまで返され続けます。','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI機能はオプションです。言語ルーティング、hreflang、言語切り替え、翻訳グループシステムは、プロバイダーが設定されていなくても動作します。','AI Limits & Security'=>'AIの制限とセキュリティ','AI provider returned an empty response.'=>'AIプロバイダーが空の応答を返しました。','AI Usage'=>'AI使用状況','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120〜160文字を目標にしてください。空白のままにすると抜粋の代替を使用します。','All time'=>'全期間','Allow editors to lock individual blocks'=>'編集者が個々のブロックをロックできるようにします','Allow Gutenberg template-editing mode on post screens'=>'投稿画面でGutenbergのテンプレート編集モードを許可します','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'言語割り当て、翻訳関係、メタ記述、用語集、翻訳メモリもアンインストール時に削除します','Also generate meta description'=>'メタ説明も生成する','Alternative (server-side):'=>'代替（サーバー側）：','An unknown error occurred.'=>'不明なエラーが発生しました。','and'=>'および','Anthropic (Claude)'=>'Anthropic（Claude）','any'=>'いずれか','API calls saved by cache'=>'キャッシュされたAPI呼び出し','API Key'=>'APIキー','API Keys'=>'APIキー','API Keys Tab'=>'APIキータブ','API Response Cache'=>'API応答キャッシュ','Applied ✓'=>'適用完了 ✓','Apply failed — please try again.'=>'適用に失敗しました — もう一度お試しください。','Apply to Block'=>'ブロックに適用','Apply to Editor'=>'エディターに適用','Apply to Footnote'=>'脚注に適用','Apply to Meta Description'=>'メタディスクリプションに適用','Apply translation'=>'翻訳を適用','Applying…'=>'適用中…','Approximate size'=>'おおよそのサイズ','Archive'=>'アーカイブ','Archive: %s'=>'アーカイブ：%s','Authors and above (edit_published_posts)'=>'著者以上（edit_published_posts）','Behavior'=>'動作','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'動作：AIプリセット（リテラル、バランス、クリエイティブ）を選択し、サイト全体のカスタムプロンプト指示を追加し、自動投稿保存翻訳を有効または無効にし、翻訳メモリを設定します。','Block Content'=>'ブロックコンテンツ','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'訪問者の言語に翻訳が存在しないため、現在のページがソース言語で表示されている場合に丁寧な通知を表示します。これは、Lingua ForgeルーターのLINGUAFORGE_LANG_FALLBACK_ACTIVE信号によって制御されており、リクエストロケールに翻訳が存在する場合は何も発しません。','Block Editor'=>'ブロックエディター','block keywordfallback'=>'フォールバック','block keywordi18n'=>'i18n','block keywordlanguage'=>'言語','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'翻訳','Block locking'=>'ブロックロック','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'カスタム投稿タイプ用に登録されたブロックパターン。翻訳ボタンを使って言語バリアントを作成します。翻訳された内容はここに保存され、ブロックエディタのパターンインサーターから任意のCPT投稿にコピーしたり、同期パターン（再利用可能ブロック）の出発点として使用できます。','block titleMissing Translation Notice'=>'翻訳なし通知','Block translation reuses'=>'ブロック翻訳の再利用','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'投稿間で共有されるブロックレベルの翻訳キャッシュ。有効にすると、同一のブロック（同じマークアップ、言語ペア、用語集）は、AIを再呼び出しする代わりにメモリから提供されます。設定 → 動作で構成します。','Browser language redirect'=>'ブラウザ言語リダイレクト','Built-in preset instructions:'=>'内蔵プリセット指示:','Bulletize (•-prefixed)'=>'箇条書き（•-プレフィックス）','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ブロックレベルで翻訳のキャッシュを保存し、再利用可能なコンテンツ（共有フッター、サイドバー、アコーディオン、定型文の多い法的セクション）がAPI呼び出しを毎回行わないようにします。有効にすると、翻訳フローは各投稿をブロックに解析し、キャッシュ内の各ブロックを検索し、キャッシュされていないブロックだけを一括リクエストでAIに送信します。用語集の編集やコンプライアンスプリセットの変更は自動的に影響を受けたキャッシュ翻訳を無効にします。統計を表示し、メンテナンスでキャッシュをクリアします。','cached'=>'キャッシュ済み','Cached API responses'=>'キャッシュされたAPI応答','Cached block translations'=>'キャッシュされたブロック翻訳','Cancel'=>'キャンセル','Cannot determine target language from slug.'=>'スラッグからターゲット言語を特定できません。','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'サイトが生成できるAIの使用量を制限し、有料AI呼び出しをトリガーできるユーザーロールを制限します。既にあるユーザごとのレート制限（30リクエスト/分、ハードコーディング）の上に乗っています。','chars'=>'文字数','Chunk translated'=>'翻訳されたチャンク','Chunk translated to:'=>'翻訳されたチャンク：','Clear'=>'クリア','Clear All'=>'すべてクリア','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'すべてのキャッシュされたAI結果をクリアしますか？今後のリクエストはキャッシュの再構築まで新しいAPI呼び出しをトリガーします。','Clear API Response Cache'=>'API応答キャッシュをクリア','Clear Debug Files'=>'デバッグファイルをクリア','Clear hints'=>'ヒントをクリア','Clear input'=>'入力をクリア','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'翻訳メモリ全体をクリアしますか？今後の翻訳はキャッシュを再構築します。','Clear Translation Memory'=>'翻訳メモリをクリア','Close'=>'閉じる','Close language panel'=>'言語パネルを閉じる','Close popover'=>'ポップオーバーを閉じる','Compliance Preset'=>'コンプライアンスプリセット','Content generated'=>'コンテンツが生成されました','Content Generator'=>'コンテンツ生成器','Content ready'=>'コンテンツ準備完了','Contributors and above — default (edit_posts)'=>'投稿者以上 — デフォルト（edit_posts）','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'AIに送信されるコンテンツの量と応答の大きさを制御します。空白のままにすると、組み込みのデフォルト（プレースホルダーとして表示）を使用します。大きなページが切り捨てられる場合はこれらの値を上げ、小さくしてAPIコストを削減します。','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AIコンテンツジェネレーター機能のトークン予算と入力制限を制御します。空白のままにすると、内蔵のデフォルトが使用されます。','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'管理者がプラグインを削除したときの動作を制御します。プラグイン設定とAIキャッシュは常に削除されます。言語割り当てと翻訳関係はデフォルトで保持されるため、誤ってアンインストールしたり再インストールした場合でも前の状態から再開できます。','Conversational'=>'会話調','Copied ✓'=>'コピー完了 ✓','Copy'=>'コピー','Copy markup'=>'マークアップをコピー','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'結果をコピーして必要な場所に貼り付けてください（例：脚注フィールドに直接）。','Copy to safe storage'=>'セーフストレージにコピー','Could not add entry: source term and target term are required.'=>'エントリーを追加できませんでした：ソース用語とターゲット用語は必須です。','Could not copy the file. Check that the uploads folder is writable.'=>'ファイルをコピーできませんでした。アップロードフォルダに書き込み権限があるか確認してください。','Could not instantiate the provider.'=>'プロバイダーをインスタンス化できませんでした。','Could not save the file. Check that the uploads folder is writable.'=>'ファイルを保存できませんでした。アップロードフォルダに書き込み権限があるか確認してください。','Could not save the glossary entry.'=>'用語集のエントリを保存できませんでした。','CPT Block Patterns'=>'CPTブロックパターン','Create'=>'作成','Create missing'=>'不足しているものを作成','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'投稿タイプ "%s" の翻訳を作成するには、アクティブな連携が必要です。必要な連携がインストールされて有効になっていることを確認してください。','Creating…'=>'作成中…','Creative / Marketing'=>'クリエイティブ / マーケティング','Creative / Marketing instructions'=>'クリエイティブ / マーケティング指示','Current content (will be overwritten)'=>'現在の内容（上書きされます）','Current title'=>'現在のタイトル','Current: {current}'=>'現在: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'現在、%s定数から継承されています。ここで値を選択すると上書きされます。','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'現在、ブロックコメント属性プレースホルダー（wp:detailsサマリーフィールドなど）を使用する投稿はスキップされ、既存の単一呼び出し翻訳パスにフォールバックします。','Currently:'=>'現在：','Custom'=>'カスタム','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'日次AIクォータに達しました（%1$dリクエスト）。UTCの%2$sにリセットされます。','Daily request limit'=>'1日のリクエスト制限','Debug Files'=>'デバッグファイル','Debug files cleared. %d file was removed.'=>'デバッグファイルがクリアされました。%dファイルが削除されました。' . "\0" . '','Debug logging'=>'デバッグログ','Debug logging disabled.'=>'デバッグログ記録は無効です。','Debug logging enabled.'=>'デバッグログが有効になっています。','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'デバッグ：AIプロンプトとAPI応答をローカルファイルに記録するデバッグログを有効にします。トラブルシューティング後は無効にしてください — デバッグモードはすべてのAIリクエストでファイルを書き込みます。','Delete'=>'削除','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'デバッグディレクトリ内のすべての.txtファイルを削除しますか？ディレクトリ自体は残るので、今後のデバッグ書き込みは正常に行われます。`define( \'LINGUAFORGE_AI_DEBUG\', true );`をwp-config.phpで設定して、この切り替えを上書きすることもできます。','Delete all files for this override (both .mo and .po)?'=>'この上書きのすべてのファイル（.moと.poの両方）を削除しますか？','Delete content data on uninstall'=>'アンインストール時にコンテンツデータを削除','Delete this glossary entry?'=>'この用語集のエントリを削除しますか？','Describe what to write — topic, key points, structure…'=>'書く内容を説明してください — トピック、重要ポイント、構成…','Directory'=>'ディレクトリ','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'プロンプト調整中や、すべてのリクエストをAIプロバイダーに届ける必要がある場合は無効にします。無効にしてもキャッシュされたエントリは削除されません — 再有効化で復元されます。忙しいサイトでは、無効にするとAPI支出が即座に増加することが予想されます。','Display'=>'表示','Displays the Lingua Forge language switcher.'=>'Lingua Forgeの言語切替器を表示します。','Documentation'=>'ドキュメント','Done'=>'完了','Done — {done} of {total} post(s) fixed.'=>'完了 — {done} / {total} の投稿を修正しました。','Down'=>'下向き','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.orgから直接WordPressコアの言語パックをダウンロードしてインストールします。インストール後、そのロケールはURLルーティングとAI翻訳ワークフローで利用可能になります。利用可能な言語のリストは必要に応じて取得されます — 下のボタンをクリックして読み込みます。','Dropdown direction'=>'ドロップダウンの方向','Editors and above (edit_others_posts)'=>'編集者以上（edit_others_posts）','Enable API response caching'=>'API応答キャッシュを有効にする','Enable block-level translation cache reuse across posts'=>'投稿間でブロックレベルの翻訳キャッシュの再利用を有効にします','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'少なくとも1つのAIプロバイダーのAPIキーを入力してください。キーはAES-256-GCMを使用してサイト固有の秘密（LINGUAFORGE_SECRET）で暗号化されます。秘密をローテーションせずにデータベースエクスポートを共有しないでください。','environment variable'=>'環境変数','Error'=>'エラー','Expand'=>'拡張','Expected: {expected}'=>'期待される: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'追加のガイダンス — トーン、スタイル、制約、ターゲット層…','Extra guidance — tone, style, constraints…'=>'追加のガイダンス — トーン、スタイル、制約…','Failed. Please try again.'=>'失敗しました。もう一度お試しください。','Feature'=>'機能','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'機能は2つの層にグループ化されています。各層とプロバイダーの正確なモデル識別子を入力してください。空白のフィールドはビルトインのデフォルトを使用します（プレースホルダーとして表示）。アクティブなプロバイダーのモデルだけが実行時に呼び出されます。切り替える予定がある場合は事前に設定してください。','File copied to safe storage successfully.'=>'ファイルが安全なストレージに正常にコピーされました。','Files'=>'ファイル','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'ファイルは以下のディレクトリに保存されます。翻訳の問題を診断するのに役立ちます — 必要なものが得られたらオフにして、ファイルが蓄積しないようにしてください。wp-config.phpからも`define( \'LINGUAFORGE_AI_DEBUG\', true );`を使ってこの動作を強制的に設定できます。これは切り替えを上書きします。','Filter'=>'フィルター','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'linguaforge_debug_dirを使って、デバッグ出力を非公開の場所にリダイレクトします。','Fix'=>'修正','Fix All'=>'すべて修正','Fix all links'=>'すべてのリンクを修正','Fix all parts'=>'すべてのパーツを修正','Fix Links'=>'リンクを修正','Fix Nav'=>'ナビゲーションを修正','Fix Parts'=>'パーツを修正','Fix Template'=>'テンプレートを修正','Fixing {n} / {total}…'=>'{n} / {total} を修正中…','Fixing…'=>'修正中…','Flush Permalink Rules'=>'パーマリンクルールをフラッシュ','Flush Permalinks'=>'パーマリンクをフラッシュ','Footnote Content'=>'脚注の内容','footnote(s) translated — applied together with content.'=>'脚注が翻訳されました — コンテンツと一緒に適用されました。','Footnotes'=>'脚注','Footnotes payload (advanced)'=>'脚注ペイロード（高度な設定）','Forbidden'=>'禁止されています','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.phpのLINGUAFORGE_AI_DEBUG定数によって強制的にOFFになっています。この行を削除して、ここからこの切り替えを制御してください。','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.phpのLINGUAFORGE_AI_DEBUG定数によって強制的にONになっています。この行を削除して、ここからこの切り替えを制御してください。','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong>の中で<strong>{scanned}</strong>の投稿にわたって<strong>{parts}</strong>を見つけました。','From'=>'から','Front Page'=>'フロントページ','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSEローカリゼーション：このタブから直接、フルサイトエディティングのテンプレートやテンプレートパーツのスキャフォールド、翻訳、リンク修正を行います。','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'アクティブテーマからシードされたFSEテンプレート。サイトエディタで作成し、カスタマイズします。','Full Article'=>'全文記事','Full post'=>'全文投稿','General'=>'一般','Generate'=>'生成','Generate Content'=>'コンテンツ生成','Generate content…'=>'コンテンツを生成…','Generate Excerpt'=>'抜粋を生成','Generate Meta Description'=>'メタディスクリプションを生成','Generated Content'=>'生成されたコンテンツ','Generated meta description'=>'生成されたメタディスクリプション','Generating…'=>'生成中…','Generation failed.'=>'生成に失敗しました。','Getting started'=>'はじめに','Global AI preset'=>'グローバルAIプリセット','Global default (%s)'=>'グローバルデフォルト (%s)','Glossary'=>'用語集','Glossary entry added.'=>'用語集エントリーが追加されました。','Glossary entry removed.'=>'用語集エントリーが削除されました。','Glossary Tab'=>'用語集タブ','Google (Gemini)'=>'Google（Gemini）','Hide'=>'非表示','Hints'=>'ヒント','Home link text'=>'ホームリンクのテキスト','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'翻訳に表示されるべき形。AIに対して、内容をそのまま保持するよう指示するために、ソース用語と同じ値を入力してください。','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'アイコン + ラベル','Icon only'=>'アイコンのみ','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'チェックすると、プラグインをアンインストールしたときに、すべての言語割り当て、翻訳関係、メタ記述、ページごとのプリセット、AI用語集、翻訳メモリがこのサイトのすべての投稿から恒久的に削除されます。これは元に戻せません。サイトから多言語サポートを完全に削除する場合を除き、チェックを外してください。','Improve writing'=>'文章を改善','Informative'=>'情報提供','Input tokens'=>'入力トークン','Install'=>'インストール','Install a Language'=>'言語をインストール','Installing…'=>'インストール中…','Instructions (optional)'=>'指示（任意）','Instructions / key points'=>'指示 / 重要ポイント','Integration API'=>'統合API','Internal Link Fixer'=>'内部リンク修正ツール','Introduction only'=>'序文のみ','Invalid file reference.'=>'無効なファイル参照です。','Invalid filename.'=>'無効なファイル名です。','Invalid language.'=>'無効な言語。','Invalid locale code.'=>'無効なロケールコードです。','Invalid or primary language.'=>'無効または主要な言語。','Invalid post type.'=>'無効な投稿タイプ。','Invalid template part.'=>'無効なテンプレート部分。','Invalid template type.'=>'無効なテンプレートタイプ。','Key points, ideas, or structure to build from…'=>'ポイント、アイデア、または構造の構築に役立つもの…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'キーはAES-256-CBCで暗号化され、WordPressデータベースに保存されます。暗号化の秘密はWordPressの認証ソルト（wp-config.php）から導出されるため、平文のキーはデータベースに触れません。','Language'=>'言語','Language %s installed successfully.'=>'言語 %s が正常にインストールされました。','Language (optional)'=>'言語（任意）','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'このサーバーでは言語のインストールが無効になっています（DISALLOW_FILE_MODSが設定されています）。','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'このサーバーでは言語のインストールが無効になっています。wp-config.phpにDISALLOW_FILE_MODS定数が設定されています。WP-CLIを使って手動で言語パックをインストールしてください：wp language core install de_DE','Language label'=>'言語ラベル','Language Overrides'=>'言語の上書き','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'言語上書き：Lingua Forge UI文字列のカスタム.po/.mo上書きファイルを管理します。これを使用してプラグインファイルを直接編集する代わりに — 上書きはアップデートを超えて保持されます。','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'言語パックのインストールに失敗しました。すでにインストールされているか、ロケールコードが正しくないか、サーバーがファイル書き込みをブロックしている可能性があります。','Language Setup'=>'言語設定','Language Switcher'=>'言語切替器','Language switcher'=>'言語切り替え器','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'テーマのテンプレートパーツの言語固有のコピー。スキャフォールディング後、テンプレートは言語固有のパーツを参照するように更新されます。','Language:'=>'言語:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'ルーターに現在認識されている言語（インストールされたWordPressロケールパックと主要な言語から派生）。下のセクションで追加の言語パックをインストールして、ルーティングと翻訳に利用できる言語を増やしてください。','Last 30 days'=>'過去30日間','Last 7 days'=>'過去7日間','Lead paragraph (≤60 w)'=>'リード段落（≤60語）','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'モデルフィールドを空白のままにすると、その階層の組み込みデフォルトを使用します。プレースホルダーテキストは使用されるモデルを示します。','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'ブランド名や言語に依存しない用語で、どの言語から翻訳しても適用されるべき場合は空白のままにします。','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'すべてのターゲット言語にこのエントリを適用するには空白のままにします。ブランド名や略語、すべての翻訳でそのまま保持すべき用語に最適です。','Leave blank to keep the existing key. Enter a new value to replace it.'=>'既存のキーを維持するには空白のままにします。新しい値を入力して置き換えます。','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'空白のままにしてビルトインのデフォルトを使用します。保存済みの上書きをクリアすると、次回保存時にデフォルトに戻ります。','Legal / Compliance'=>'法的 / コンプライアンス','Legal / Compliance instructions'=>'法的 / コンプライアンス指示','Light'=>'ライト','Light (default — fast and cost-effective)'=>'ライト（デフォルト — 高速かつコスト効率的）','Light (fast and cost-effective — Haiku / Flash)'=>'ライト（高速かつコスト効率的 — Haiku / Flash）','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'ライト：メタディスクリプションや抜粋生成に使用 — 高速で低コスト。','Limit results to pages in the given Lingua Forge language code.'=>'指定されたLingua Forgeの言語コードのページに結果を限定します。','Limits'=>'制限','Lingua Forge'=>'リンガフォージ','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forgeは、多言語ルーティング、AI駆動の翻訳、hreflang SEOタグ、言語切り替えをWordPressサイトに追加します。','Lingua Forge AI Tools'=>'Lingua Forge AIツール','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forgeは、言語間で編集動作を一貫させるために、デフォルトで2つのGutenberg機能を制限しています。完全なGutenberg / FSE機能が必要な場合は、ここでオプトインしてください。','Lingua Forge Settings'=>'Lingua Forge設定','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forgeは、冗長なAI API呼び出しを避けるために2つの独立したキャッシング層を使用します。各層を検査・管理するには、下のタブを使用してください。','Lingua Forge uses two model tiers per provider:'=>'Lingua Forgeは、各プロバイダーに対して2つのモデル階層を使用します。','Lingua Forge — Quick Translate'=>'リンガフォージ — クイック翻訳','Lingua Forge — Settings'=>'Lingua Forge — 設定','link(s)'=>'リンク','Links'=>'リンク','Load available languages'=>'利用可能な言語を読み込む','Loading…'=>'読み込み中…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translateはカスタム翻訳をwp-content/languages/loco/に保存します。これはWPコアのアップデートやプラグインの再インストール、Loco Translateの削除によって静かに消去される可能性があります。ここにファイルをコピーすると、それらはLingua Forgeのi18n-overridesディレクトリに移動され、これらのイベントを通じて持続し、すべてのリクエストで自動的に読み込まれます。','Loco Translate — Copy to Safe Storage'=>'Loco Translate — セーフストレージにコピー','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI機能をトリガーできる最低のWordPress能力。これを厳しく設定すると、投稿者やトライアルアカウントが有料のAI呼び出しを行うのを防ぎます。個別の機能は、linguaforge_required_capabilityフィルターを通じて上書き可能です。','Maintenance'=>'メンテナンス','Maintenance Tab'=>'メンテナンスタブ','Make casual'=>'カジュアルにする','Make concise'=>'簡潔にする','Make formal'=>'フォーマルにする','Mark citations needed'=>'引用が必要な箇所にマーク','Max context characters'=>'コンテキストの最大文字数','Max hints characters'=>'ヒントの最大文字数','Max input characters'=>'最大入力文字数','Max output tokens'=>'最大出力トークン数','Maximum characters accepted from the input field. Default: 8 000.'=>'入力フィールドから受け付ける最大文字数。デフォルト：8,000。','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'ヒントが提供されていない場合に、シードコンテキストとしてAIに渡される既存の投稿内容の最大文字数。デフォルト：6,000。','Maximum characters read from the Hints field. Default: 2 000.'=>'ヒントフィールドから読み取る最大文字数。デフォルト：2,000。','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'AIに送信される投稿内容の最大文字数。0は制限なしを意味し、常に全内容が送信されます（推奨）。プロバイダーに厳しいコンテキストウィンドウがある場合のみ非ゼロの値を設定してください。内容が切り詰められるとPHPエラーログに警告が記録されます。','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AIが単一の翻訳応答で生成できる最大トークン数。翻訳が静かに途中で切れる場合は、この値を増やしてください。デフォルトは16,000です。','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AIが1回の生成で生成できる最大トークン数。記事全体が切り捨てられる場合はこれを増やしてください。デフォルト：8,192。','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AIが1回のクイック翻訳で生成できる最大トークン数。デフォルト：2,000。','Meta Description'=>'メタディスクリプション','Meta Description, Excerpt Generator'=>'メタディスクリプション、抜粋生成','Minimum role'=>'最低ロール','Missing pattern name or language.'=>'パターン名または言語が欠落しています。','Mode'=>'モード','Model'=>'モデル','Model tier'=>'モデルの階層','Models'=>'モデル','Models Tab (General)'=>'モデルタブ（一般）','Most recent cached block'=>'最新のキャッシュされたブロック','Most recent cached response'=>'最新のキャッシュされた応答','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'WordPressの多言語ルーティング、SEOメタタグ、AIコンテンツツール。言語検出、URLルーティング、hreflang、メタディスクリプション、AIを活用した抜粋、メタ、翻訳機能を組み合わせています。','Name displayed in this language. Leave empty to use the source name.'=>'この言語で表示される名前。空白のままにするとソース名が使用されます。','Navigation'=>'ナビゲーション','Navigation has no content to translate.'=>'ナビゲーションに翻訳する内容がありません。','Navigation not found.'=>'ナビゲーションが見つかりません。','Navigation posts are translated via the Router tab, not this button.'=>'ナビゲーション投稿はルータータブ経由で翻訳され、このボタンではありません。','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'ナビゲーションの翻訳にはアクティブなAIプロバイダーが必要です。APIキーをAPIキータブで設定してください。','Navigations'=>'ナビゲーション','Network error — could not reach the WordPress AJAX endpoint.'=>'ネットワークエラー — WordPressのAJAXエンドポイントに到達できませんでした。','No %s version found in this translation group.'=>'この翻訳グループに %s バージョンが見つかりません。','No AI provider configured.'=>'AIプロバイダーが設定されていません。','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'選択した期間 (%s) でのAI使用状況は記録されていません。上の範囲を広げて選択してください。','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'まだAI使用状況は記録されていません。エディターが翻訳、メタ説明の生成、その他のAI機能を使用すると、合計がここに表示されます。','No API key configured for this provider.'=>'このプロバイダーのAPIキーが設定されていません。','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'内蔵指示はありません — 各AI機能は独自の調整済みデフォルトを使用します。以下のカスタムプロンプト指示フィールドに記入して、サイト全体のルールを追加してください。','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'まだカスタムLoco Translateファイルは見つかりません。Loco Translateで翻訳を保存するとここに表示されます。','No file was selected.'=>'ファイルが選択されていません。','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'現在のフィルターに一致する用語集のエントリがありません。すべてのエントリを表示するにはフィルターをクリアするか、下に新しいエントリを追加してください。','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'まだ用語集のエントリはありません。下に追加して翻訳の用語を強制適用し始めましょう。','No internal links found to update.'=>'更新する内部リンクが見つかりません。','No language-specific template parts found to map.'=>'マッピングするための言語固有のテンプレート部分が見つかりません。','No navigation references needed updating.'=>'更新が必要なナビゲーション参照はありません。','No override files uploaded yet.'=>'まだアップロードされた上書きファイルはありません。','No response from provider — check the error log for details.'=>'プロバイダーからの応答がありません — 詳細はエラーログを確認してください。','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'二次言語が設定されていません。上の言語パックをインストールしてテンプレートのスキャフォールディングを有効にしてください。','No source content found to translate.'=>'翻訳するためのソースコンテンツが見つかりません。','No source page linked yet.'=>'まだソースページがリンクされていません。','No template part references needed updating.'=>'更新が必要なテンプレート部分の参照はありません。','No {lang} translation registered (TRID missing)'=>'{lang}の翻訳が登録されていません（TRIDが欠落しています）','Notes'=>'ノート','Notice message'=>'通知メッセージ','Notice settings'=>'通知設定','Oldest cached block'=>'最も古いキャッシュされたブロック','Oldest cached response'=>'最も古いキャッシュされた応答','Only .mo files are accepted.'=>'.moファイルのみが受け付けられます。','OpenAI (GPT)'=>'OpenAI（GPT）','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'編集者向けの任意のコンテキスト（例："ASIC = Application-Specific Integrated Circuit; 技術的文脈では英語のまま保持"）。','Output'=>'出力','Output tokens'=>'出力トークン','overridden'=>'上書き済み','Override file deleted.'=>'上書きファイルが削除されました。','Override file uploaded successfully.'=>'上書きファイルのアップロードに成功しました。','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'このページの翻訳とコンテンツ生成のためのAIプリセットを上書きします。他の機能は常にグローバルプリセットを使用します。','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'このページの翻訳とコンテンツ生成のためのAIプリセットを上書きします。サイト全体のカスタムプロンプト指示（設定 → 動作）は、この選択に関係なく常に各リクエストに追加されます。','Overview'=>'概要','Page'=>'ページ','Part'=>'パーツ','Paste a footnote, sentence, or any snippet here…'=>'フットノート、文章、または任意のスニペットをここに貼り付けてください…','Paste text, or select text in the editor first…'=>'テキストを貼り付けるか、まずエディタでテキストを選択してください…','Paste text, or select text on the page first…'=>'まずテキストを貼り付けるか、ページ上でテキストを選択してください…','Paste your API key…'=>'APIキーを貼り付けてください…','Path prefix — example.com/de/'=>'パスプレフィックス — example.com/de/','Pattern'=>'パターン','Pattern has no content to translate.'=>'翻訳する内容のないパターンです。','Pattern not found.'=>'パターンが見つかりません。','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'パターンが翻訳され保存されました。コンテンツをブロックエディタのパターン挿入ツールを通じてCPT投稿にコピーするか、再利用可能ブロックの出発点として使用してください。','Pattern translation failed.'=>'パターンの翻訳に失敗しました。','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'AI生成の翻訳、メタディスクリプション、抜粋、コンテンツのための投稿ごとのキャッシュ。常に有効 — 別のトグルは不要です。内容やAIプロバイダー/モデルが変更されると自動的に無効化されます。ツールバーの「↺ 再翻訳」ボタンや下の「クリア」をクリックして新しいAPI呼び出しを強制します。','Permalink rules flushed successfully.'=>'パーマリンクルールが正常にフラッシュされました。','Permission denied.'=>'アクセス拒否されました。','Persuasive'=>'説得力','PHP constant'=>'PHP定数','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'翻訳してはいけない用語や特定の方法で常にレンダリングされる必要がある用語（例：ブランド名、商品名、頭字語）をピン留めします。用語集の制約は、すべてのAI翻訳リクエスト（投稿翻訳、メタディスクリプション、抜粋、FSEテンプレート翻訳）に挿入されます。','Plain language'=>'平易な言葉','Please enter some instructions first…'=>'まずいくつかの指示を入力してください…','Please enter some text first…'=>'まずいくつかのテキストを入力してください…','Post'=>'投稿','Post not found.'=>'投稿が見つかりません。','Post Types'=>'投稿タイプ','Prefilled from excerpt. Edit to override.'=>'抜粋から事前入力されています。上書きするには編集してください。','Primary Language'=>'プライマリ言語','Primary language'=>'プライマリ言語','Primary language saved.'=>'プライマリ言語が保存されました。','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'主要言語：既存コンテンツが書かれている言語です。すべての翻訳はこの言語から生成されます。これを変更しても投稿は移動・削除されません。','Processing…'=>'処理中…','Provider'=>'プロバイダー','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'プロバイダーからテキストが返されませんでした。詳細な失敗理由についてはWordPressのエラーログを確認してください。','Quality'=>'品質','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'品質（デフォルト — Sonnet / GPT-4o / Gemini Pro）','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'品質（ソネット / GPT-4o / ジェミニ Pro）','Quality: used for post translation and content generation — higher quality, higher cost.'=>'品質：投稿翻訳やコンテンツ生成に使用 — 高品質でコストも高くなります。','Quick Translate'=>'クイック翻訳','Quick Translation'=>'クイック翻訳','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'スニペット/チャンクモードに使用されるクイック翻訳 — ツールバー、エディター、ブロックポップオーバーから短い文章をオンデマンドで翻訳します。フルページ翻訳とは異なる軽量な設定を使用し、応答を高速かつコスト効率的に保ちます。','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'GutenbergのcanLockBlocksを再有効化します。特定のブロックの移動や削除を防止する必要がある編集テンプレートに便利です。','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateModeを再有効化します。投稿レベルのテンプレート上書きが意図的なフルサイト編集ワークフローの核心です。','Re-generates and updates the cached result.'=>'キャッシュされた結果を再生成して更新します。','Re-scan'=>'再スキャン','Re-scanning…'=>'再スキャン中…','Re-translate'=>'再翻訳','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'ブラウザのAccept-Languageヘッダーに基づいて、訪問者を好みの言語にリダイレクトします','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'さらに洗練 — 例：「短くする」や「フォーマルなトーンを使う」…','Refine further:'=>'さらに改善：','Refinement'=>'改善（%d回目）','Refinement failed — please try again.'=>'改善に失敗しました — もう一度お試しください。','Refining…'=>'改善中…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'URLのプレフィックス、言語固有のスラッグ、アーカイブの書き換えを同期させるために、WordPressの書き換えルールを再生成します。主要な言語を変更したり、新しい言語サポートを追加した後に必要です。','Remove stored key'=>'保存されたキーを削除','Report an issue on GitHub'=>'GitHubで問題を報告','Request failed — please try again.'=>'リクエストに失敗しました — もう一度お試しください。','Request failed.'=>'リクエストに失敗しました。','Request failed. Check your connection.'=>'リクエストに失敗しました。接続を確認してください。','Request failed. Please try again.'=>'リクエストに失敗しました。もう一度お試しください。','Requests'=>'リクエスト','Reset'=>'リセット','Result will appear here…'=>'結果はここに表示されます…','Retranslate'=>'再翻訳','Retranslating…'=>'再翻訳中…','Review carefully — links and slugs not updated.'=>'注意深く確認してください — リンクとスラッグが更新されていません。','Review translation before applying'=>'適用前に翻訳を確認してください','Revise'=>'改訂','Revision'=>'改訂','Revision Type'=>'改訂タイプ','Router'=>'ルーター','Router Tab'=>'ルータータブ','Save Debug Setting'=>'デバッグ設定を保存','Save Router Settings'=>'ルーター設定を保存','Save Settings'=>'設定を保存','Save the post to persist changes.'=>'変更を保存して投稿を確定します。','Save Uninstall Setting'=>'アンインストール設定を保存','Saved to the meta description field when you apply.'=>'適用時にメタディスクリプション欄に保存されます。','Scan failed: '=>'スキャン失敗: ','Scan request failed. Please try again.'=>'スキャンリクエストに失敗しました。もう一度お試しください。','Scanning posts for broken language links…'=>'壊れた言語リンクをスキャンしています…','Search'=>'検索','Search Results'=>'検索結果','Security check failed — file path is not permitted.'=>'セキュリティチェックに失敗しました。ファイルパスが許可されていません。','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'管理する言語を選択して、そのFSEテンプレート、テンプレートパーツ、ナビゲーションメニューを設定します。','Select language'=>'言語を選択','SEO character-count info'=>'SEO文字数情報','Server setup (subdomain)'=>'サーバー設定（サブドメイン）','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'サイト全体のすべての機能のデフォルトAI動作を設定します。個別の投稿は、Lingua Forgeのメタボックスを通じて翻訳とコンテンツ生成に対してこれを上書きできます。','Settings'=>'設定','Settings saved.'=>'設定が保存されました。','Show home link'=>'ホームリンクを表示','Shown when no translation exists for the visitor\'s language.'=>'訪問者の言語に翻訳が存在しない場合に表示される。','Single'=>'シングル','Single %s'=>'シングル %s','Single: %s'=>'シングル：%s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC日ごとのAIリクエストのサイト全体の上限（ツールバーの翻訳とブロックの改訂の両方をカウント）。カウンターはUTCの真夜中にリセットされます。無効にするには0に設定します。','Size'=>'サイズ','Some link fixes failed.'=>'一部のリンク修正に失敗しました。','Some nav ref fixes failed.'=>'一部のナビゲーション参照修正に失敗しました。','Some part fixes failed.'=>'一部のパーツ修正に失敗しました。','Some parts could not be created.'=>'一部のパーツを作成できませんでした。','Some templates could not be created.'=>'一部のテンプレートを作成できませんでした。','Some translations failed.'=>'いくつかの翻訳に失敗しました。','Source file not found.'=>'ソースファイルが見つかりません。','Source lang'=>'ソース言語','Source language'=>'ソース言語','Source term'=>'ソース用語','Standard'=>'標準','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'標準は各機能の調整された温度を使用します：翻訳はT=0.2（正確）、クイック翻訳はT=0.4、コンテンツ生成はT=0.6（創造的）。他のプリセットはすべての機能に単一の固定温度を適用します。','Status'=>'ステータス','Status / Actions'=>'ステータス / アクション','Storytelling'=>'ストーリーテリング','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'法的、規制、医療、または技術的なコンテンツのための厳格な保存モード。有効にすると、すべてのAI機能は低サンプリング温度を使用し、以下の付録をシステムプロンプトに付加します。用語、記事番号、単位、ブランド名、規制言語はそのまま保存され、言い換えられません。','Structured Outline'=>'構造化アウトライン','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'サブドメインモードでは、すべての言語サブドメイン（例：de.example.com）をこのWordPressインストールにポイントさせる必要があります。モードを切り替えた後は、パーマリンクルールをフラッシュし、キャッシュをクリアしてください。ホームURLにwwwが含まれている場合（例：www.example.com）、lf_base_domainフィルターを使ってベアのエイペックスドメインを設定し、サブドメインが正しく構築されるようにしてください。','Subdomain — de.example.com/'=>'サブドメイン — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'対応プロバイダー：Anthropic（Claude）、OpenAI（GPT）、Google（Gemini）。一度に1つのプロバイダーのみがアクティブです。一般設定タブでアクティブなプロバイダーを選択してください。','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6、機能ごと','Target lang'=>'ターゲット言語','Target Language'=>'ターゲット言語','Target language'=>'ターゲット言語','Target term'=>'ターゲット用語','Target: 140–160 chars for optimal SERP display'=>'ターゲット：最適なSERP表示のために140〜160文字','Technical'=>'技術的','Technical / Scientific'=>'技術 / 科学','Technical / Scientific instructions'=>'技術 / 科学的指示','Template "%s" already exists.'=>'テンプレート「%s」は既に存在します。','Template "{expected}" does not exist — create it in the Site Editor first.'=>'テンプレート "{expected}" は存在しません — まずサイトエディタで作成してください。','Template has no content.'=>'テンプレートに内容がありません。','Template mode'=>'テンプレートモード','Template not found or not stored in the database.'=>'テンプレートが見つからないか、データベースに保存されていません。','Template part "%s" already exists.'=>'テンプレート部分「%s」は既に存在します。','Template part has no content.'=>'テンプレート部分に内容がありません。','Template part not found or not stored in the database.'=>'テンプレート部分が見つからないか、データベースに保存されていません。','Template Parts'=>'テンプレートパーツ','Templates'=>'テンプレート','Test connection'=>'接続テスト','Testing…'=>'テスト中…','Text domain / locale'=>'テキストドメイン / ロケール','Text to translate'=>'翻訳するテキスト','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API応答キャッシュは、すべてのAIリクエストの生の結果（翻訳、メタディスクリプション、抜粋、コンテンツ生成）を保存し、入力のハッシュ（内容、言語ペア、プロバイダー、モデル）をキーとします。同一の入力を持つリクエストはキャッシュから提供され、API呼び出しは行われません。キャッシュは翻訳メモリとは異なります：翻訳メモリはブロックレベルで動作し、投稿間で共有されます。API応答キャッシュは機能レベルで動作し、投稿ごとにキー付けされます。','The editor did not accept the content — please try again.'=>'エディターが内容を受け入れませんでした — もう一度お試しください。','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ライト層は、上記のモデル表で設定された高速モデルを使用します（デフォルト：俳句 / フラッシュ）。スニペットの全ページモードと同じ翻訳精度が必要な場合は、クオリティに切り替えてください。','The phrase as it appears in the source text.'=>'ソーステキストに表示されるフレーズ。','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'プライマリ言語は常にサイトのルートで提供されます — パスモードではURLプレフィックスなし、サブドメインモードでは言語サブドメインなし。その他の言語は、以下のURL構造設定に応じて、/lang/パスプレフィックス（例：example.com/de/）または言語サブドメイン（例：de.example.com）を使用します。','The source page has no footnotes.'=>'ソースページにはフットノートがありません。','The upload failed — please try again.'=>'アップロードに失敗しました。もう一度お試しください。','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'これらのフットノートはソースページからのもので、参考のためにここに表示されています。ブロックエディタを使ってこのページに追加してください。','This is the source page. Footnotes are edited directly in the block editor.'=>'これはソースページです。フットノートはブロックエディタで直接編集されます。','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'このキーは現在、サーバー %s から提供されており、ここでは削除できません。上に新しいキーを入力して、データベースの値に上書きしてください。','Tip: to reset a model to the built-in default, clear the field and save.'=>'ヒント：モデルをビルトインのデフォルトにリセットするには、フィールドをクリアして保存してください。','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'カスタム暗号化シークレット（派生したwp_salt値の代わり）を使用するには、これをwp-config.phpに追加します：','Today'=>'今日','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'機能、プロバイダー、モデルごとにトークン消費量を集計。成功したAI呼び出しごとに記録されます。テスト接続のピングは意図的に除外されており、合計を歪めません。基礎となる表は日次で集計されているため、下のウィンドウを選択して表示します。','Tone'=>'トーン','tone'=>'トーン','Tone:'=>'トーン:','Too many AI requests. Please retry in %d seconds.'=>'AIリクエストが多すぎます。%d秒後に再試行してください。','Total'=>'合計','Total tokens'=>'合計トークン','Translate'=>'翻訳','Translate / Revise'=>'翻訳 / 改訂','Translate / Revise block'=>'ブロックの翻訳 / 改訂','Translate all'=>'すべて翻訳','Translate chunk'=>'チャンクを翻訳','Translate Content'=>'コンテンツを翻訳','Translate missing'=>'未翻訳を翻訳','Translate page…'=>'ページを翻訳…','Translated content'=>'翻訳された内容','Translated Names'=>'翻訳された名前','Translated title'=>'翻訳されたタイトル','Translated to:'=>'翻訳済み：','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'翻訳済み。サイトエディタで確認 — 内部リンク、ナビゲーションURL、テンプレートスラッグは自動的に更新されません。','Translating…'=>'翻訳中…','Translation'=>'翻訳','Translation Caching'=>'翻訳キャッシング','Translation found but permalink could not be generated'=>'翻訳は見つかりましたが、パーマリンクを生成できませんでした','Translation Limits'=>'翻訳の制限','Translation Limits & Behavior'=>'翻訳の制限と動作','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'翻訳の制限：どのユーザーロールがAI翻訳をトリガーできるかを制御し、月間トークン予算を設定します。予算を超えると、その月がリセットされるまでAI呼び出しが停止します。','Translation Memory'=>'翻訳メモリ','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'翻訳メモリは、コンテンツハッシュ、言語ペア、プロバイダー、モデルによってAIの結果をキャッシュします。投稿を編集するとキャッシュエントリが無効になり、次の翻訳呼び出しで新しい結果が得られます。','Translation Memory cleared. %d cached block was removed.'=>'翻訳メモリがクリアされました。%d個のキャッシュされたブロックが削除されました。' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'翻訳メモリ：コンテンツハッシュごとに完全な翻訳済み投稿を保存します。内容が変更されていなくてもすべての投稿の再翻訳を強制したい場合は、これをクリアしてください。','Translation workflow'=>'翻訳ワークフロー','Translation, Content Generator'=>'翻訳、コンテンツ生成','Type'=>'タイプ','Uli Hake'=>'ハケ・ウリ','Uninstall Behaviour'=>'アンインストール動作','Uninstall setting saved.'=>'アンインストール設定が保存されました。','unknown error'=>'不明なエラー','Unknown provider.'=>'不明なプロバイダー。','Up'=>'上向き','Upload .mo file'=>'.moファイルをアップロード','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'特定のロケールに対してサードパーティプラグインの文字列を上書きするために、コンパイル済みの.moファイルをアップロードします。例："room"の代わりに"apartment"を使用するカスタムVikBooking翻訳。ファイルはWordPressの命名規則に従う必要があります：{textdomain}-{locale}.mo（例：vikbooking-ca.mo）。これらはアップロードフォルダに保存され、プラグインの更新を超えて保持されます。','Upload Override'=>'上書きアップロード','URL could not be mapped to a post — check the link target exists'=>'URLが投稿にマッピングできませんでした — リンクのターゲットが存在するか確認してください','URL structure'=>'URL構造','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL構造：パスプレフィックスモード（example.com/de/）はサーバーの変更を必要としません。サブドメインモード（de.example.com）はワイルドカードDNSレコード、ワイルドカードSSL証明書、およびWebサーバーの設定変更が必要です — サーバー設定ガイドを参照してください。','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'このページの上部のタブを使って各エリアを設定します。ルータータブの変更は即座に反映されます。AIキーとモデル設定の変更は次のAIリクエストに適用されます。','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'言語ペアごとに管理されるユーザー管理の用語表。エントリーは翻訳システムのプロンプトに追加され、AIが好ましい用語を一貫して使用します。ドメイン語彙（"kWp"、"PPA"、"相互接続点"）、翻訳してはいけないブランド名、標準化された規制表現にとって重要です。両方の言語フィールドは任意です："ソース言語"を空白のままにすると、どの言語から翻訳しても適用されます。"ターゲット言語"を空白のままにすると、すべてのターゲット言語に一度に適用されます。','Using custom meta description.'=>'カスタムメタディスクリプションを使用しています。','View'=>'表示','View built-in default'=>'ビルトインデフォルトを表示','View details'=>'詳細を見る','View Lingua Forge details'=>'Lingua Forgeの詳細を見る','Visit plugin site'=>'プラグインサイトを訪問','Warning:'=>'警告：','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'デバッグログが有効になっている場合（以下のトグルまたはwp-config.phpでLINGUAFORGE_AI_DEBUGを定義）、翻訳とFSEテンプレートの翻訳機能は、トラブルシューティングのために生のAIプロンプトと応答をディスクに書き込みます。このセクションを使用して出力を監視し、必要に応じてクリアしてください。大きなページではファイルがすぐに増えることがあります。出力先ディレクトリはlinguaforge_debug_dirフィルターで設定します。','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'有効にすると、言語クッキーやURLの言語プレフィックスがない初回訪問者は、最も近い一致する言語バージョンにリダイレクトされます。ブラウザの優先言語がアクティブなルーター言語に含まれない場合はリダイレクトはスキップされます。スイッチャーを通じて言語を選択した訪問者は、クッキーが優先され、今後の訪問ではブラウザヘッダーは無視されます。','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'フルページ翻訳に使用するモデルの階層。品質は上記のModelsテーブルで設定されたモデルを使用し、正確な長文翻訳に推奨されます。速度やコストを優先し、内容が短い場合のみライトに切り替えます。','WP-CLI reference'=>'WP-CLIリファレンス','Write AI prompts and responses to disk for troubleshooting'=>'トラブルシューティングのためにAIのプロンプトと応答をディスクに書き込む','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'キーを定数や環境変数として定義することもできます（例：wp-config.php）。これらのソースは、データベースキーが保存されていない場合に自動的にフォールバックとして使用されます。','You do not have permission to manage these settings.'=>'これらの設定を管理する権限がありません。','You do not have permission to read this post.'=>'この投稿を読む権限がありません。','{n} stale path(s)'=>'{n} の古いパス','— Any source language —'=>'— いずれかのソース言語 —','— Any target language —'=>'— いずれかのターゲット言語 —','— Any target —'=>'— いずれかのターゲット —','— Any —'=>'— いずれか —','— auto-detect —'=>'— 自動検出 —','— select a language —'=>'— 言語を選択 —','— toggle in Settings → Behavior.'=>'— 設定→動作の切り替え。','← Back'=>'← 戻る','↑ Detected from current post'=>'↑ 現在の投稿から検出','↺ Re-translate'=>'↺ 再翻訳','↺ Refine'=>'↺ 改善','↺ Refresh'=>'↺ 更新','↺ Refreshing…'=>'↺ 更新中…','⚠ Borderline'=>'境界線付近','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ <strong>{lang}</strong>の投稿が見つかりません。すべての翻訳された投稿の言語メタが<strong>{lang}</strong>に設定されていることを確認してください。','⚠ No changes'=>'⚠ 変更なし','⚠ No changes — re-scan?'=>'⚠ 変更なし — 再スキャンしますか？','✅ Fixed ({n})'=>'✅ 修正済み ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong>の壊れたリンクやテンプレートの不一致は見つかりませんでした。<strong>{scanned}</strong>の投稿とページをスキャンし、すべてのチェックに合格しました。ヘッダー、フッター、サイドバーのテンプレート部分のリンクは含まれていません — それらを個別に確認するには「テンプレート部分を修正」ボタンを使用してください。','✅ Template fixed'=>'✅ テンプレートが修正されました','✓ All parts created.'=>'✓ すべてのパーツが作成されました。','✓ All templates created.'=>'✓ すべてのテンプレートが作成されました。','✓ All translated.'=>'✓ すべて翻訳完了。','✓ Configured'=>'✓ 設定済み','✓ Connection OK'=>'✓ 接続OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ コンテンツが生成されました — オーバーレイを見て、レビュー、改善、適用してください。','✓ Done'=>'✓ 完了','✓ Enabled'=>'✓ 有効','✓ Good length'=>'良い長さ','✓ In safe storage'=>'✓ セーフストレージに保存済み','✓ Language installed.'=>'✓ 言語がインストールされました。','✓ Links fixed.'=>'✓ リンクが修正されました。','✓ Nav refs fixed.'=>'✓ ナビゲーション参照が修正されました。','✓ Parts fixed.'=>'✓ パーツが修正されました。','✓ Pattern translated.'=>'✓ パターンが翻訳されました。','✓ Refined — review the updated draft above.'=>'✓ 改善完了 — 上記の更新されたドラフトを確認してください。','✓ Translation saved'=>'✓ 翻訳が保存されました','✗ Disabled'=>'✗ 無効','✗ Error:'=>'✗ エラー:','✗ Failed:'=>'✗ 失敗:','✗ Not configured'=>'✗ 未設定','✗ Too long'=>'長すぎる','✗ Too short'=>'短すぎる','❌ Failed'=>'❌ 失敗','📄 Wrong template'=>'📄 間違ったテンプレート','📍 Stale path (page moved)'=>'📍 古いパス（ページが移動しました）']];
